import csv,numpy as np,collections
rows=list(csv.DictReader(open('responses.csv')))
y=np.array([int(r['rating']) for r in rows]); p=np.load('iter_1/candidate_4/scratch/p.npy')
E=[[int(x) for x in r['number_set'].split(',')] for r in rows]; T=np.array([int(r['target']) for r in rows])
lo=np.array([min(e) for e in E]); hi=np.array([max(e) for e in E]); n=np.array([len(e) for e in E])
