for ps in ['below','inside','above']:
  for a,b in [(0,1),(1,6),(6,15),(15,30),(30,100)]:
    s=(pos==ps)&(dist>=a)&(dist<b)
    if s.sum()>20: print(ps,a,b,s.sum(),y[s].mean().round(3),p[s].mean().round(3), 'LLgap',round(np.sum(y[s]*np.log(p[s])+(1-y[s])*np.log(1-p[s])),1))
# by n and position
for k in range(1,5):
  for ps in ['below','inside','above']:
    s=(pos==ps)&(n==k)
    if s.sum(): print(k,ps,s.sum(),y[s].mean().round(3),p[s].mean().round(3))
